class AuthGate extends StatefulWidget { const AuthGate({super.key}); @override State<AuthGate> createState()=>_AuthGateState(); }
class _AuthGateState extends State<AuthGate> {
  final auth=AuthService(); bool loading=true; Map<String,dynamic>? profile;
  @override void initState(){super.initState(); _load();}
  Future<void> _load() async { try { final p=await auth.currentProfile(); if(p!=null){ try { profile=await auth.fetchMe(); } catch (_) { await auth.logout(); } } } finally { if(mounted)setState(()=>loading=false); } }
  @override Widget build(BuildContext context) { if(loading)return const Scaffold(body:Center(child:CircularProgressIndicator())); return profile==null?LoginPage(onLogin:(p)=>setState(()=>profile=p)):HomePage(profile:profile!,onLogout:()async{await auth.logout();if(mounted)setState(()=>profile=null);}); }
}
